output:
module "storage" {
  source = "./modules/storage"

  bucket_name = "acme-uploads"
  environment = "staging"
}

module "iam_user" {
  source = "github.com/acme-modules/terraform-aws-iam-user?ref=v1.2.0"

  name    = "ci-bot"
  pgp_key = var.pgp_key
}

variable "pgp_key" {
  type = string
}

# modules/kms/main.tf
variable "description" {
  type = string
}

variable "deletion_window" {
  type    = number
  default = 10
}

resource "aws_kms_key" "this" {
  description             = var.description
  deletion_window_in_days = var.deletion_window
}

resource "aws_kms_alias" "this" {
  name          = "alias/${var.description}"
  target_key_id = aws_kms_key.this.key_id
}

# modules/kms/outputs.tf
output "key_arn" {
  value = aws_kms_key.this.arn
}

# main.tf
module "app_key" {
  source = "./modules/kms"

  description      = "acme-app"
  deletion_window = 7
}

output "app_key_arn" {
  value = module.app_key.key_arn
}

module "queue_dev" {
  source = "./modules/queue"

  name    = "orders-dev"
  max_redrive = 5
}

module "queue_prod" {
  source = "./modules/queue"

  name    = "orders-prod"
  max_redrive = 10
}

module "network" {
  source = "./modules/network"

  cidr_block = "10.20.0.0/16"
}

output "vpc_id" {
  description = "VPC id created by the network module"
  value       = module.network.vpc_id
}

module "eks" {
  source  = "terraform-aws-modules/eks/aws"
  version = "20.8.4"

  cluster_name    = "acme-cluster"
  cluster_version = "1.29"

  vpc_id     = module.vpc.vpc_id
  subnet_ids = module.vpc.private_subnets

  eks_managed_node_groups = {
    default = {
      instance_types = ["m5.large"]
      min_size       = 2
      max_size       = 5
      desired_size   = 2
    }
  }
}

module "vpc" {
  source = "./modules/network"

  cidr_block = "10.30.0.0/16"
}

module "alb_sg" {
  source  = "terraform-aws-modules/security-group/aws"
  version = "5.1.2"

  name        = "alb-sg"
  description = "Security group for the application load balancer"
  vpc_id      = var.vpc_id

  ingress_cidr_blocks = [var.vpc_cidr]
  ingress_rules       = ["https-443-tcp"]
}

variable "vpc_id" {
  type = string
}

variable "vpc_cidr" {
  type = string
}

module "bastion_sg" {
  source  = "terraform-aws-modules/security-group/aws"
  version = "5.1.2"

  name   = "bastion-sg"
  vpc_id = var.vpc_id

  ingress_cidr_blocks = var.admin_cidrs
  ingress_rules       = ["ssh-tcp"]
}

variable "vpc_id" {
  type = string
}

variable "admin_cidrs" {
  type = list(string)
}

module "blob_storage" {
  source = "github.com/acme-modules/terraform-aws-buckets//modules/private-bucket?ref=v2.1.0"

  bucket_name = "acme-archive"
  force_destroy = false
}

# modules/app/main.tf
variable "settings" {
  type = map(string)
}

resource "aws_cloudwatch_log_group" "this" {
  for_each = var.settings

  name              = "/app/${each.key}"
  retention_in_days = tonumber(each.value)
}

output "log_group_names" {
  value = [for g in aws_cloudwatch_log_group.this : g.name]
}

# main.tf
module "app_logs" {
  source = "./modules/app"

  settings = {
    api     = "14"
    worker  = "30"
  }
}

module "network" {
  source = "./modules/network"

  name       = "shared"
  cidr_block = "10.40.0.0/16"
}

module "compute" {
  source = "./modules/compute"

  subnet_ids         = module.network.private_subnet_ids
  security_group_ids = [module.network.default_security_group_id]
  instance_count     = 2
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.40"
    }
  }
}

terraform {
  required_version = ">= 1.5"

  # Private registry modules resolve through the host configured in .terraformrc
  # with an address like app.terraform.io/acme/vpc/aws
}

module "vpc" {
  source = "app.terraform.io/acme/vpc/aws"

  version = "1.4.0"
  name    = "private-registry-vpc"
  cidr    = "10.50.0.0/16"
}

module "tags" {
  source = "./modules/tags"

  project     = "acme"
  environment = "prod"
  owner       = "platform"
}

module "bucket" {
  source = "./modules/tagged-bucket"

  name = "acme-prod-artifacts"
  tags = module.tags.tags
}

module "names" {
  source = "./modules/names"

  count_per_env = 1
}

resource "aws_sqs_queue" "jobs" {
  name = "jobs-${module.names.suffix}"
}

module "log_archive" {
  source = "./modules/log-archive"

  bucket_name = "acme-log-archive"
}

module "security" {
  source = "./modules/security hub"

  log_bucket_arn = module.log_archive.bucket_arn
}

module "network" {
  source = "./modules/network"

  flow_log_bucket_arn = module.log_archive.bucket_arn
  depends_on          = [module.security]
}

module "website" {
  source  = "terraform-aws-modules/s3-bucket/aws"
  version = "4.1.1"

  bucket = "acme-static-website"
  acl    = "public-read"

  control_object_ownership = true
  object_ownership         = "BucketOwnerPreferred"

  website_index_document = "index.html"
}

output "website_endpoint" {
  value = module.website.s3_bucket_website_endpoint
}

module "alb" {
  source  = "terraform-aws-modules/alb/aws"
  version = "9.4.0"

  name               = "acme-alb"
  load_balancer_type = "application"

  vpc_id          = var.vpc_id
  subnets         = var.public_subnet_ids
  security_groups = [module.alb_sg.security_group_id]

  target_groups = {
    app = {
      name      = "app"
      port      = 8080
      protocol  = "HTTP"
      target_type = "instance"
    }
  }
}

module "alb_sg" {
  source = "./modules/alb-sg"

  vpc_id = var.vpc_id
}

variable "vpc_id" {
  type = string
}

variable "public_subnet_ids" {
  type = list(string)
}

# modules/queue/variables.tf
variable "name" {
  type = string
}

variable "visibility_timeout" {
  type    = number
  default = 60
}

variable "tags" {
  type    = map(string)
  default = {}
}

# modules/queue/main.tf
resource "aws_sqs_queue" "this" {
  name                       = var.name
  visibility_timeout_seconds = var.visibility_timeout
  tags                       = var.tags
}

# modules/queue/outputs.tf
output "queue_arn" {
  value = aws_sqs_queue.this.arn
}

# main.tf
module "payments_queue" {
  source = "./modules/queue"

  name              = "payments"
  visibility_timeout = 120
  tags = {
    Team = "payments"
  }
}
